    fold L T CTX TOP in TAL, TLO, THI, CXLO, CXHI, CXLEN, CXAL, TOP23, TOPHI. pose proof aceil_bounds as ACB.
    pose proof (lowhigh_Pimg _ _ TLO) as TI. pose proof (lowhigh_Pband _ _ TLO) as TB. pose proof (lowhigh_big _ _ CXLO ltac:(clear; lia)) as CX63.
    assert (SLO : l_stk_lo L <= lo) by (subst L; rewrite EL; exact LOL).
    assert (LOIMG : ACEIL <= lo) by (clear - LOL STKLO_OK; lia).
    assert (TOP1 : TOP <= 2^47) by (clear - TOPHI STKHI47; lia).
    assert (TOP2 : SP + 16 <= 2^47) by (clear - SPT HTOPHI STKHI47; subst L; lia).
    assert (SPH : SP <= 2^62) by (clear - TOP2; lia).
    assert (WFKh : WFK h) by (exact (WFK_of_awf' h AWF HV)).
    (* [comment removed for export] *)
    rewrite HLB in HIN. unfold blocks, live in HIN. apply in_map_iff in HIN as (k & EK & Hk). apply filter_In in Hk as [Hk STk]. apply Z.eqb_eq in STk.
    injection EK as EA EN. symmetry in EA. symmetry in EN.
    ddestruct (chunk_ext' h k WL WR WK Hk) as (N0 & E1 & E2 & E3 & E4 & [E5 E5'] & E6 & ARM).
    dpose (chunk_geom' h k WL WR WK Hk) as (RZ16 & _ & U8). pose proof (ck_user16 h k WL WK Hk) as U16.
    dpose WK as (WKF & NDK & WK3). pose proof (proj1 (Forall_forall _ _) WKF k Hk) as (WN32 & _ & WP & _).
    set (p := ck_user k) in *. set (nx := nfix (ck_n k)).
    assert (NXB : 0 <= nx < 2^32) by (subst nx; unfold nfix; clear - WN32; lia).
    (* [comment removed for export] *)
    dpose VWF as (TWF & APT & _).
    assert (TC : T + 4096 <= CTX \/ CTX + 0x10000 <= T).
    { destruct (APT _ _ (tr_of_T h) (tr_of_ctx h)) as [E|X]; [exfalso; injection E; subst L CTX; clear - CXLEN; lia|].
      unfold t_hi in X. cbn [t_lo t_len] in X. subst T CTX L. clear - X CXLEN. lia. }
    assert (EXT_T : T + 4096 <= ext_lo k \/ ext_hi k <= T).
    { destruct ARM as [(PK & C30 & R1 & R2 & _)|(PK & i & Ni & XL & XH)].
      - pose proof (WR (ck_cls k) ltac:(unfold kNumClasses; clear - C30; lia)) as W. cbn zeta in W. ddestruct W as (_ & AUMU & _).
        destruct (user_in_hull h (ck_cls k) (ext_lo k) WL WR ltac:(clear - C30; lia) ltac:(clear - R1 R2 E1 E2 E4 AUMU; lia)) as (HX1 & _).
        destruct (user_in_hull h (ck_cls k) (ext_hi k - 1) WL WR ltac:(clear - C30; lia) ltac:(clear - R1 R2 E1 E2 E4 AUMU; lia)) as (HX2 & _).
        pose proof (z_T_hull h (F_geom AL h mo WFKh HK0)) as Z0. unfold zapart in Z0. cbn [fst snd] in Z0. subst T L. clear - Z0 HX1 HX2 E1 E2 E4. lia.
