    dpose GT as (UNW & (ds & PCL) & (jq0 & jq1 & J2768) & (xs & bs & STX & LXS & STB & HL)). fold L T in UNW, PCL, STX, STB, J2768.
    destruct xs as [|x0 [|x1 [|x2 [|x3 [|x4 [|x5 [|x6 [|x7 xs8]]]]]]]]; try (cbn in LXS; discriminate).
    pose proof (u64arr_cells m _ _ STX) as STX'. cbn [map] in STX'.
    change (C8 x0 :: C8 x1 :: C8 x2 :: C8 x3 :: C8 x4 :: C8 x5 :: C8 x6 :: C8 x7 :: map C8 xs8)
      with ([C8 x0; C8 x1; C8 x2; C8 x3; C8 x4] ++ [C8 x5; C8 x6] ++ (C8 x7 :: map C8 xs8)) in STX'.
    apply rw_cells_app in STX' as [_ STX']. apply rw_cells_app in STX' as [TST _].
    cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ length map app] in TST.
    match type of TST with rw_cells _ _ ?a _ => replace a with (T + 2824) in TST by (clear; lia) end.
    dpose GI as (IA1 & IA2 & IA3 & (cs2 & IA4 & IS4) & (p0 & p1 & IA5 & IP) & (cs4 & IA6 & IS6) & (cs5 & IA7 & IS7)).
    rewrite (zeros_eq 0x40000) in IA3.
    dpose GM as (SHLO & SHHI & STKW & TW & CTXW & FSW). fold L in SHLO, SHHI, STKW, TW, CTXW, FSW.
    (* [comment removed for export] *)
    pose proof (proj1 (Forall_forall _ _) GC k Hk) as (HDR & MAG & USH). ddestruct HDR as (b1 & cid & HDR & B13 & B1B & CIDB).
