      rewrite (K68 A0 j ltac:(right; exact Hz1) ltac:(clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia) ltac:(clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia) ltac:(clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia)
                 ltac:(clear - Hz1 Hz2 ZHS STKZ SPL BHU1 BHU2; try subst STK; lia)
