      rewrite (K56 A0 j ltac:(right; clear - Hz1; lia) ltac:(clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia) ltac:(clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia)
                 ltac:(apply RFX_out; [clear - Hz1 Hz2 ZHS STKZ SPL; try subst STK; lia| clear - Hz1 Hz2 ZSB STKZ SPL; try subst STK; lia| clear - Hz1 Hz2 ZTS STKZ SPL; try subst STK; lia]) x Hx).
